.top-songs-section,
.featured-artists-section {
  margin-bottom: 3rem;
}

.top-songs-section h2,
.featured-artists-section h2 {
  text-align: center;
  margin-bottom: 2rem;
  color: #a3d8ff;
}

.songs-grid,
.artists-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.song-card,
.artist-card {
  background: rgba(9, 13, 25, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 1rem;
  padding: 1.5rem;
  text-align: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.song-card:hover,
.artist-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.4);
}

.song-card h3,
.artist-card h3 {
  color: #f2f8ff;
  margin-bottom: 0.5rem;
  font-size: 1.25rem;
}

.song-card p,
.artist-card p {
  color: rgba(231, 238, 252, 0.8);
  margin-bottom: 0.5rem;
}

.song-card span {
  color: #7bffea;
  font-size: 0.9rem;
}

@media (max-width: 991px) {
  .navbar-nav {
    gap: 0.4rem;
  }

  .page-content {
    padding: 1.4rem;
  }

  .hero-section {
    padding: 3rem 1.5rem;
  }

  .hero-actions {
    flex-direction: column;
    align-items: center;
  }

  .songs-grid,
  .artists-grid {
    grid-template-columns: 1fr;
  }
}

